  <title>Image Preview</title>
  <style>
    :root {
      color-scheme: dark;
      --bg: #0b0f17;
      --panel: rgba(18, 24, 38, 0.92);
      --panel-strong: #121826;
      --text: #e5e7eb;
      --muted: #9ca3af;
      --line: rgba(148, 163, 184, 0.18);
      --accent: #ef4444;
      --accent-hover: #dc2626;
      --shadow: 0 30px 80px rgba(0, 0, 0, 0.55);
    }

    * {
      box-sizing: border-box;
    }

    body {
      margin: 0;
      min-height: 100vh;
      display: grid;
      place-items: center;
      padding: 24px;
      font: 16px/1.5 system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
      color: var(--text);
      background:
        radial-gradient(circle at top, rgba(59, 130, 246, 0.16), transparent 35%),
        radial-gradient(circle at bottom right, rgba(239, 68, 68, 0.12), transparent 30%),
        var(--bg);
    }

    .preview {
      width: min(100%, 720px);
      background: linear-gradient(180deg, rgba(20, 27, 41, 0.96), rgba(12, 17, 28, 0.96));
      border: 1px solid var(--line);
      border-radius: 24px;
      box-shadow: var(--shadow);
      overflow: hidden;
    }

    .preview__image {
      aspect-ratio: 16 / 10;
      background:
