          center/cover;
    }

    .preview__content {
      padding: 22px;
      display: grid;
      gap: 14px;
    }

    .preview__title {
      margin: 0;
      font-size: 1.1rem;
      font-weight: 650;
      letter-spacing: 0.01em;
    }

    .preview__meta {
      margin: 0;
      color: var(--muted);
      font-size: 0.95rem;
    }

    .actions {
      display: flex;
      justify-content: flex-start;
    }

    .trigger {
      appearance: none;
      border: 0;
      border-radius: 999px;
      padding: 0.85rem 1.15rem;
      font: inherit;
      font-weight: 600;
      color: #fff;
      background: linear-gradient(180deg, #ef4444, #c81e1e);
      box-shadow: 0 10px 24px rgba(239, 68, 68, 0.28);
      cursor: pointer;
      transition: transform 150ms ease, filter 150ms ease, background 150ms ease;
    }

    .trigger:hover {
      filter: brightness(1.05);
      transform: translateY(-1px);
    }

    .trigger:focus-visible,
    .modal__close:focus-visible,
    .modal__confirm:focus-visible,
    .modal__cancel:focus-visible {
      outline: 3px solid rgba(96, 165, 250, 0.9);
      outline-offset: 2px;
    }

    .modal {
      position: fixed;
      inset: 0;
      display: grid;
      place-items: center;
      padding: 24px;
      background: rgba(3, 7, 18, 0.68);
      opacity: 0;
      visibility: hidden;
      pointer-events: none;
      transition: opacity 180ms ease, visibility 180ms ease;
    }

    .modal.is-open {
      opacity: 1;
      visibility: visible;
      pointer-events: auto;
    }

    .modal__dialog {
      width: min(100%, 440px);
      background: linear-gradient(180deg, rgba(23, 30, 46, 0.98), rgba(14, 19, 31, 0.98));
      border: 1px solid rgba(148, 163, 184, 0.16);
      border-radius: 20px;
      box-shadow: var(--shadow);
      overflow: hidden;
      transform: translateY(10px) scale(0.98);
      transition: transform 180ms ease;
    }

    .modal.is-open .modal__dialog {
      transform: translateY(0) scale(1);
    }

    .modal__header,
    .modal__body,
    .modal__footer {
      padding-left: 22px;
      padding-right: 22px;
    }

    .modal__header {
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 16px;
      padding-top: 20px;
      padding-bottom: 12px;
      border-bottom: 1px solid var(--line);
    }

    .modal__title {
      margin: 0;
      font-size: 1.05rem;
      font-weight: 650;
    }

    .modal__close {
      appearance: none;
      border: 0;
      border-radius: 999px;
      width: 36px;
      height: 36px;
      color: var(--text);
      background: rgba(148, 163, 184, 0.12);
      cursor: pointer;
      font-size: 1.2rem;
      line-height: 1;
    }

    .modal__body {
      padding-top: 18px;
      padding-bottom: 20px;
      color: var(--muted);
    }

    .modal__footer {
      display: flex;
      justify-content: flex-end;
      gap: 12px;
      padding-bottom: 22px;
    }

    .modal__cancel,
    .modal__confirm {
      appearance: none;
      border: 1px solid transparent;
      border-radius: 999px;
      padding: 0.78rem 1.1rem;
      font: inherit;
      font-weight: 600;
      cursor: pointer;
      transition: transform 150ms ease, filter 150ms ease, background 150ms ease;
    }

    .modal__cancel {
      color: var(--text);
      background: rgba(148, 163, 184, 0.12);
      border-color: rgba(148, 163, 184, 0.16);
    }

    .modal__confirm {
      color: #fff;
      background: linear-gradient(180deg, var(--accent), var(--accent-hover));
      box-shadow: 0 10px 24px rgba(239, 68, 68, 0.25);
    }

    .modal__cancel:hover,
    .modal__confirm:hover {
      transform: translateY(-1px);
      filter: brightness(1.04);
    }
  </style>
</head>
<body>
  <main class="preview" aria-label="Image preview">
    <div class="preview__image" role="img" aria-label="A moody city skyline at night"></div>
    <div class="preview__content">
      <h1 class="preview__title">Night Skyline</h1>
      <p class="preview__meta">A photo saved in your library.</p>
      <div class="actions">
        <button class="trigger" type="button" aria-haspopup="dialog" aria-controls="delete-dialog">
          Delete image
        </button>
      </div>
    </div>
  </main>

  <div class="modal" id="delete-dialog" role="dialog" aria-modal="true" aria-labelledby="delete-title" aria-hidden="true">
    <div class="modal__dialog">
      <div class="modal__header">
        <h2 class="modal__title" id="delete-title">Delete this image?</h2>
        <button class="modal__close" type="button" aria-label="Close dialog">×</button>
      </div>
      <div class="modal__body">
        This will permanently remove the image from your library. This action cannot be undone.
      </div>
      <div class="modal__footer">
        <button class="modal__cancel" type="button">Cancel</button>
        <button class="modal__confirm" type="button">Delete</button>
      </div>
    </div>
  </div>

  <script>
    const trigger = document.querySelector('.trigger');
    const modal = document.getElementById('delete-dialog');
    const closeButtons = modal.querySelectorAll('.modal__close, .modal__cancel');
    const confirmButton = modal.querySelector('.modal__confirm');

    function openModal() {
      modal.classList.add('is-open');
      modal.setAttribute('aria-hidden', 'false');
      closeButtons[0].focus();
    }

    function closeModal() {
      modal.classList.remove('is-open');
      modal.setAttribute('aria-hidden', 'true');
      trigger.focus();
    }

    trigger.addEventListener('click', openModal);
    closeButtons.forEach((button) => button.addEventListener('click', closeModal));
    confirmButton.addEventListener('click', closeModal);

    modal.addEventListener('click', (event) => {
      if (event.target === modal) closeModal();
    });

    document.addEventListener('keydown', (event) => {
      if (event.key === 'Escape' && modal.classList.contains('is-open')) {
        closeModal();
      }
    });
  </script>
</body>
</html>
